/** Named timestamps generated by tools/cues.py, independent of composition FPS. */
export interface NarrationCue {
  timeMs: number;
}

export interface CueDocument {
  version: 1;
  cues: Record<string, NarrationCue>;
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/** Parse a JSON import or fetch once, before using cues in frame calculations. */
export const parseCueDocument = (value: unknown): CueDocument => {
  if (!isObject(value) || value.version !== 1 || !isObject(value.cues)) {
    throw new Error('Expected a version 1 narration cue document');
  }
  const entries: [string, NarrationCue][] = [];
  for (const [name, cue] of Object.entries(value.cues)) {
    if (
      !name.trim() || !isObject(cue) || typeof cue.timeMs !== 'number' ||
      !Number.isFinite(cue.timeMs) || cue.timeMs < 0
    ) {
      throw new Error(`Cue ${JSON.stringify(name)} requires a finite, non-negative timeMs`);
    }
    entries.push([name, { timeMs: cue.timeMs }]);
  }
  if (entries.length === 0) throw new Error('The cue document contains no cues');
  return { version: 1, cues: Object.fromEntries(entries) };
};

/** Use the composition's actual FPS, even when the JSON includes cached frames. */
export const cueFrame = ({
  document,
  name,
  fps,
}: {
  document: CueDocument;
  name: string;
  fps: number;
}): number => {
  if (!Number.isFinite(fps) || fps <= 0) throw new Error('Cue FPS must be greater than zero');
  if (!Object.prototype.hasOwnProperty.call(document.cues, name)) {
    throw new Error(`Unknown narration cue ${JSON.stringify(name)}`);
  }
  const frame = Math.round(document.cues[name].timeMs / 1000 * fps);
  if (!Number.isSafeInteger(frame)) throw new Error(`Cue ${JSON.stringify(name)} exceeds the frame range`);
  return frame;
};
